/* Expansion is staged during the lottery window; completed seasons remain immutable. */
let expansionBusy=false, expansionProtectionTeam=0;
const expansionFilters={pos:'all',age:45,salary:100,ovr:0};
function expansionWindow(){return draftReady()&&!state.draft?.order.length&&!faActive()}
function expansionData(){return state.expansion||(state.expansion={active:null,history:[]})}
function expansionCap(club,year=state.year){const event=state.expansion?.history.find(h=>h.team===club.id);return salaryCap()*(event&&year===event.year+1&&event.config.cap==='reduced'?.8:1)}
function expansionConfig(v){
 const c={};for(const k of ['city','name','abbr','arenaName','divisionId','newDivision','conferenceId','marketSize','primary','secondary','cap','seed','preset'])c[k]=String(v[k]||'').trim();c.abbr=c.abbr.toUpperCase();c.preset=c.preset.toUpperCase();if(c.preset&&!franchisePreset(c.preset))throw Error('Choose a valid franchise preset.');if(!c.preset)delete c.preset;
 // Metro population: the form sends millions, a stored config holds people, and configs saved before
 // population existed keep their market tier through its default population.
 const market=typeof v.population==='number'?(validMetroPopulation(v.population)?{population:v.population,marketSize:marketSizeForPopulation(v.population)}:null):v.population!==undefined&&v.population!==''?metroPopulationEdit(v.population):['Small','Medium','Large'].includes(c.marketSize)?withMetroPopulation({marketSize:c.marketSize},{keepTier:true}):null;
 if(!market)throw Error('Enter a metro population between 0.1M and 30M.');c.population=market.population;c.marketSize=market.marketSize;
 for(const k of ['capacity','ticket','protect','maximum','target','fee','hype'])c[k]=Number(v[k]);c.rebuild=v.rebuild===true||v.rebuild==='on';
 if(!c.city||c.city.length>35||!c.name||c.name.length>35||!c.arenaName||c.arenaName.length>80||!/^[A-Z0-9]{2,5}$/.test(c.abbr))throw Error('Enter a city, team name, arena and unique 2–5 character abbreviation.');
 if(![c.primary,c.secondary].every(s=>/^#[0-9a-f]{6}$/i.test(s))||!['Small','Medium','Large'].includes(c.marketSize)||!['standard','reduced','clean'].includes(c.cap)||!['first','fourth','equal'].includes(c.seed))throw Error('Choose valid colors, market, cap and draft settings.');
 const ranges={capacity:[5000,30000],ticket:[10,300],protect:[0,14],maximum:[1,2],target:[5,30],fee:[0,10000],hype:[0,100]};for(const [k,[min,max]] of Object.entries(ranges))if(!Number.isInteger(c[k])||c[k]<min||c[k]>max)throw Error('Invalid '+k+' setting.');
 if(!c.rebuild)throw Error('Enable the schedule rebuild to admit a new franchise.');return c;
}
function expansionAvailable(a=expansionData().active){if(!a)return [];const used=new Set(a.picks.map(x=>x.id));return state.teams.flatMap(t=>{const taken=a.picks.filter(x=>x.from===t.id).length;if(taken>=a.config.maximum||t.roster.length-taken<=rosterMinimum())return [];return t.roster.filter(p=>!used.has(p.id)&&!(a.protected[t.id]||[]).includes(p.id)).map(p=>({p,t}))})}
function expansionCapacity(a){return state.teams.reduce((n,t)=>n+Math.max(0,Math.min(a.config.maximum,t.roster.length-rosterMinimum(),t.roster.filter(p=>!(a.protected[t.id]||[]).includes(p.id)).length)),0)}
async function expansionCommit(action){if(expansionBusy||!ownerCanManage())return;const before=snapshotState();expansionBusy=true;try{action();if(await save()===false)throw Error('Could not save expansion changes.');}catch(e){state=before;toast(e.message)}finally{expansionBusy=false;render()}}
async function beginExpansion(event){event.preventDefault();const values=Object.fromEntries(new FormData(event.target));return expansionCommit(()=>{
 if(!expansionWindow())throw Error('Expansion opens after the playoffs and before the draft lottery.');const data=expansionData();if(data.active||data.history.some(h=>h.year===state.year))throw Error('One expansion franchise may be admitted per lottery window.');if(state.teams.length>=36)throw Error('The league supports up to 36 teams.');
 const c=expansionConfig(values);if(c.target<rosterMinimum()||c.target>rosterMaximum())throw Error("Roster target must fit the league roster limits.");if(state.teams.some(t=>t.abbr===c.abbr))throw Error('That abbreviation is already in use.');if(c.newDivision){if(c.newDivision.length>35||state.divisions.length>=30||!state.conferences.some(x=>x.id===c.conferenceId))throw Error('Choose a conference and a division name up to 35 characters.');}else if(!state.divisions.some(d=>d.id===c.divisionId))throw Error('Choose an existing division.');
 const a={year:state.year,config:c,phase:'protection',protected:{},picks:[],before:state.teams.map(t=>({id:t.id,name:t.city+' '+t.name,conference:t.conference,division:t.division}))};for(const t of state.teams)a.protected[t.id]=[...t.roster].sort((a,b)=>b.ovr-a.ovr||a.id-b.id).slice(0,c.protect).map(p=>p.id);
 if(expansionCapacity(a)<c.target)throw Error('These rules cannot supply '+c.target+' players while preserving each team’s minimum roster. Lower protections, allow two selections per team, or wait for larger rosters.');data.active=a;
})}
async function expansionProtect(id,checked){return expansionCommit(()=>{const a=expansionData().active,t=state.teams.find(t=>t.roster.some(p=>p.id===id));if(!expansionWindow()||!a||a.phase!=='protection'||!t)throw Error('Protection lists are locked.');const ids=a.protected[t.id];if(checked&&!ids.includes(id)){if(ids.length>=a.config.protect)throw Error('Unprotect another player first.');ids.push(id)}else if(!checked)a.protected[t.id]=ids.filter(x=>x!==id)})}
async function lockExpansionProtections(){return expansionCommit(()=>{const a=expansionData().active;if(!expansionWindow()||!a||a.phase!=='protection')throw Error('No protection window is open.');if(expansionCapacity(a)<a.config.target)throw Error('Not enough eligible players. Adjust protections first.');a.phase='draft'})}
function expansionSelection(id){if(wnbaEnabled())throw Error('WNBA expansion allocation requires year-specific approval and is not supported. Existing contracts are unchanged.');const a=expansionData().active;if(!expansionWindow()||!a||a.phase!=='draft'||a.picks.length>=a.config.target)throw Error('The expansion draft is not accepting selections.');const row=expansionAvailable(a).find(x=>x.p.id===id);if(!row)throw Error('This player is protected, already selected, or the source team reached its limit.');const salary=a.picks.reduce((n,x)=>n+x.salary,0)+row.p.salary,cap=leagueRules().salaryCapType==='none'?Infinity:salaryCap()*(a.config.cap==='reduced'?.8:1),needed=a.config.target-a.picks.length-1;
 const test={...a,picks:[...a.picks,{id,from:row.t.id,salary:row.p.salary}]};const candidates=expansionAvailable(test),cheap=[];for(const t of state.teams){const remaining=Math.min(a.config.maximum-test.picks.filter(x=>x.from===t.id).length,t.roster.length-test.picks.filter(x=>x.from===t.id).length-rosterMinimum());cheap.push(...candidates.filter(x=>x.t.id===t.id).sort((a,b)=>a.p.salary-b.p.salary).slice(0,Math.max(0,remaining)).map(x=>x.p.salary))}cheap.sort((a,b)=>a-b);
 if(cheap.length<needed||salary+cheap.slice(0,needed).reduce((a,b)=>a+b,0)>cap+.001)throw Error('This pick would leave too little cap room or too few eligible players to finish the roster.');a.picks.push({id,from:row.t.id,name:row.p.name,pos:row.p.pos,salary:row.p.salary});
}
async function pickExpansionPlayer(id){return expansionCommit(()=>expansionSelection(id))}
async function undoExpansionPick(){return expansionCommit(()=>{const a=expansionData().active;if(!expansionWindow()||a?.phase!=='draft')throw Error('No active draft.');a.picks.pop()})}
async function cancelExpansion(){return expansionCommit(()=>{if(!expansionWindow())throw Error('Expansion window closed.');expansionData().active=null})}
async function finishExpansion(){return expansionCommit(()=>{
 const data=expansionData(),a=data.active;if(!expansionWindow()||!a||a.picks.length!==a.config.target)throw Error('Complete the expansion roster first.');const c=a.config,id=state.teams.length,prior=id;
 if(state.teams.some(t=>t.abbr===c.abbr))throw Error('That abbreviation is now in use. Cancel and update the franchise setup.');
 for(const t of state.teams){const selected=a.picks.filter(p=>p.from===t.id);if(t.roster.length-selected.length<rosterMinimum()||selected.length>c.maximum||selected.some(x=>!t.roster.some(p=>p.id===x.id&&p.salary===x.salary)))throw Error('A selected player or source roster changed. Undo affected picks and select again.');}
 if(leagueRules().salaryCapType!=='none'&&a.picks.reduce((n,p)=>n+p.salary,0)>salaryCap()*(c.cap==='reduced'?.8:1)+.001)throw Error('Selected payroll exceeds the expansion cap.');
 // Archive the completed season while every player is still with their original team.
 archiveFranchiseSeason();archiveStatsSeason();archiveTeamStatsSeason();archivePlayoffChampion();archiveCoachRecords();
 const oldAlignment=state.scheduleAlignment||managementAlignment(state.teams);let division=state.divisions.find(d=>d.id===c.divisionId);if(c.newDivision){division={id:'expansion-'+state.year+'-'+id,name:c.newDivision,conferenceId:c.conferenceId};state.divisions.push(division)}
 const roster=a.picks.map(pick=>{const source=state.teams[pick.from],p=source.roster.find(x=>x.id===pick.id);if(!p||a.protected[source.id].includes(p.id))throw Error('An expansion selection is no longer eligible.');source.roster=source.roster.filter(x=>x.id!==p.id);delete source.rotationPlan;p.previousTeamKey=source.key;p.contractThrough=Math.max(state.year+1,p.contractThrough||state.year);return p});
 const preset=franchisePreset(c.preset),presetColors=preset?presetTeamDefinition(preset).colors:null,colorName=(i,hex)=>presetColors&&presetColors[i].hex.toUpperCase()===hex.toUpperCase()?presetColors[i].name:['Primary','Secondary','Tertiary'][i];
 const club={id,key:'expansion-'+state.year+'-'+id,city:c.city,name:c.name,abbr:c.abbr,color:c.primary,colors:[{role:'Primary',name:colorName(0,c.primary),hex:c.primary},{role:'Secondary',name:colorName(1,c.secondary),hex:c.secondary},{role:'Tertiary',name:presetColors?presetColors[2].name:'Tertiary',hex:presetColors?presetColors[2].hex:'#FFFFFF'}],logoAtlas:preset?'preset':'expansion',logoIndex:preset?FRANCHISE_PRESETS.indexOf(preset):id%22,arenaName:c.arenaName,stadiumCapacity:c.capacity,population:c.population,marketSize:c.marketSize,conference:state.conferences.find(x=>x.id===division.conferenceId).name,division:division.name,divisionId:division.id,w:0,l:0,roster:roster.sort((a,b)=>b.ovr-a.ovr)};
 state.teams.push(club);if(state.scheduleFormat==='nba82')state.scheduleAlignment=oldAlignment;
 const entry={year:state.year,date:scheduleDate(state.day+1).toISOString().slice(0,10),team:id,priorCount:prior,config:copy(c),vote:{yes:prior,no:0},roster:copy(a.picks),before:a.before,after:[...a.before,{id,name:c.city+' '+c.name,conference:club.conference,division:club.division}],hype:c.hype};data.history.push(entry);data.active=null;
 for(const t of state.teams.slice(0,prior)){const f=financeFor(t);financePost(f,'expansionFee',c.fee/prior);const closed=f.ledger.find(x=>x.year===state.year);if(closed){closed.revenue+=c.fee/prior;closed.profit+=c.fee/prior;closed.cash=f.cash}financeSync(t)}
 ownerFor(club).plan.ticketPrice=c.ticket;financeFor(club);coachFor(club);state.draft=null;ensureDraft();
 say('LEAGUE EXPANSION: '+c.city+' '+c.name+' admitted by '+prior+'–0 vote. '+c.target+' players selected. '+money(c.fee)+' owner-funded entry fee distributed to existing franchises.');
})}
function expansionFilter(key,value){expansionFilters[key]=key==='pos'?value:Number(value);render()}
function expansionView(){const data=expansionData(),a=data.active,open=expansionWindow()&&!data.history.some(h=>h.year===state.year)&&state.teams.length<36;const input=(label,name,type='text',value='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${value}" ${extra}>${type==='range'?`<output>${value}</output>`:''}</label>`;
 const history=`<section class="panel"><div class="panelhead"><h2>Expansion history</h2></div><div class="note">${data.history.slice().reverse().map(h=>`<details><summary>${h.date} · ${escapeHTML(h.config.city+' '+h.config.name)} · Approved ${h.vote.yes}–${h.vote.no}</summary><p>Inaugural season ${seasonLabel(h.year+1)} · Owner paid ${money(h.config.fee)} · Each existing team received ${money(h.config.fee/h.priorCount)} · ${h.config.capacity.toLocaleString()} seats · Current fan hype ${expansionHype(h).toFixed(0)} / 100</p><p>${h.roster.map(p=>escapeHTML(p.name)).join(' · ')}</p><div class="exp-alignment"><div><h3>Before · ${h.priorCount} teams</h3>${expansionAlignmentText(h.before)}</div><div><h3>After · ${h.priorCount+1} teams</h3>${expansionAlignmentText(h.after)}</div></div></details>`).join('')||'<p>No expansion franchises yet.</p>'}</div></section>`;
 if(!a)return `<section class="panel"><div class="panelhead"><h2>Build a new franchise</h2><span>${state.teams.length} / 36 teams</span></div><div class="note"><p>${open?'Draft Lottery window is open. Configure one new franchise, protect players, then draft its inaugural roster.':'Expansion opens after the playoffs, before running the draft lottery. One franchise per season.'}</p>${open?expansionPresetPicker():''}<form id="expansion-form" onsubmit="beginExpansion(event)"><input type="hidden" name="preset" value=""><fieldset ${!open||expansionBusy?'disabled':''} class="exp-fields"><div id="expansion-preset-preview" class="exp-preset-preview" aria-live="polite"></div><div class="tm-grid">${input('City','city','text','','maxlength="35" required')}${input('Team name','name','text','','maxlength="35" required')}${input('Abbreviation','abbr','text','','maxlength="5" pattern="[A-Za-z0-9]{2,5}" required')}${input('Primary color','primary','color','#FA782F')}${input('Secondary color','secondary','color','#16202B')}<label>Existing division<select name="divisionId">${state.divisions.map(d=>`<option value="${d.id}">${escapeHTML(d.name)} · ${escapeHTML(state.conferences.find(x=>x.id===d.conferenceId)?.name||'')}</option>`).join('')}</select></label>${input('New division (optional)','newDivision','text','','maxlength="35"')}<label>Conference for new division<select name="conferenceId">${state.conferences.map(c=>`<option value="${c.id}">${escapeHTML(c.name)}</option>`).join('')}</select></label>${input('Arena name','arenaName','text','','maxlength="80" required')}${input('Seating capacity','capacity','number',18000,'min="5000" max="30000" required')}${metroPopulationField('population',TIER_DEFAULT_POPULATION.Medium)}${input('Ticket price ($)','ticket','range',75,'min="10" max="300" oninput="this.nextElementSibling.value=this.value"')}${input('Players protected per team','protect','number',8,'min="0" max="14" required')}${input('Maximum taken per team','maximum','number',2,'min="1" max="2" required')}<label>Roster target<select name="target">${Array.from({length:rosterMaximum()-rosterMinimum()+1},(_,i)=>`<option>${rosterMinimum()+i}</option>`).join('')}</select></label>${input('Expansion fee ($M)','fee','number',1000,'min="0" max="10000" required')}<label>First-season salary cap<select name="cap"><option value="standard">Standard cap</option><option value="reduced">80% cap for inaugural season</option><option value="clean">Standard cap / zero dead cap</option></select></label><label>First-round rookie pick<select name="seed"><option value="first">Guaranteed #1</option><option value="fourth">Guaranteed #4</option><option value="equal">Equal-odds lottery</option></select></label>${input('Initial fan hype (0–100)','hype','range',85,'min="0" max="100" oninput="this.nextElementSibling.value=this.value"')}</div><label class="exp-toggle"><input type="checkbox" name="rebuild" required> Rebuild next season’s schedule for the expanded league</label><p class="muted">New alignments use home-and-away round robin, with byes for odd team counts. Completed results are preserved. Admission records a unanimous league approval vote. All new franchises start with zero dead cap. The owner funds the fee separately from $50M operating cash. Expansion selections retain their salary and receive at least one guaranteed inaugural season.</p><button class="primary">Set up expansion draft</button></fieldset></form></div></section>${history}`;
 const pool=expansionAvailable(a).filter(({p})=>(expansionFilters.pos==='all'||p.pos===expansionFilters.pos)&&p.age<=expansionFilters.age&&p.salary<=expansionFilters.salary&&p.ovr>=expansionFilters.ovr),t=state.teams[expansionProtectionTeam]||team();return `<section class="panel"><div class="panelhead"><div><h2>${escapeHTML(a.config.city+' '+a.config.name)}</h2><small>${a.phase==='protection'?'Set protection lists':'Expansion draft room'} · ${a.picks.length} / ${a.config.target} selected</small></div><button onclick="cancelExpansion()">Cancel expansion</button></div><div class="note"><p>Selected payroll ${money(a.picks.reduce((n,p)=>n+p.salary,0))} / ${money(salaryCap()*(a.config.cap==='reduced'?.8:1))} · Maximum ${a.config.maximum} per existing team · ${rosterMinimum()}-player minimum retained</p>${a.phase==='protection'?`<label>Protection list<select onchange="expansionProtectionTeam=Number(this.value);render()">${state.teams.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${escapeHTML(x.city+' '+x.name)}</option>`).join('')}</select></label><p>${a.protected[t.id].length} / ${a.config.protect} protected. Strongest players selected automatically; adjust any team’s list.</p><div class="exp-protections">${t.roster.map(p=>`<label><input type="checkbox" ${a.protected[t.id].includes(p.id)?'checked':''} onchange="expansionProtect(${p.id},this.checked)"> ${escapeHTML(p.name)} · ${p.pos} · ${p.ovr} OVR</label>`).join('')}</div><button class="primary" onclick="lockExpansionProtections()">Lock protections & start draft</button>`:`<div class="actions"><button onclick="undoExpansionPick()" ${a.picks.length?'':'disabled'}>Undo last pick</button><button class="primary" onclick="finishExpansion()" ${a.picks.length===a.config.target?'':'disabled'}>Admit franchise & finalize draft</button></div><ol>${a.picks.map(p=>`<li>${escapeHTML(p.name)} · ${escapeHTML(state.teams[p.from].abbr)} · ${money(p.salary)}</li>`).join('')}</ol>`}</div></section><section class="panel"><div class="panelhead"><h2>Unprotected player pool</h2><span>${pool.length} available</span></div><div class="note tm-grid"><label>Position<select onchange="expansionFilter('pos',this.value)">${['all','PG','SG','SF','PF','C'].map(p=>`<option ${p===expansionFilters.pos?'selected':''}>${p}</option>`).join('')}</select></label>${['age','salary','ovr'].map(k=>`<label>${{age:'Maximum age',salary:'Maximum salary ($M)',ovr:'Minimum OVR'}[k]}<input type="number" min="0" max="1000" value="${expansionFilters[k]}" onchange="expansionFilter('${k}',this.value)"></label>`).join('')}</div><div class="scroll"><table><thead><tr><th>Player</th><th>Team</th><th>POS</th><th>Age</th><th>OVR</th><th>Salary</th><th>Selections from team</th><th>Action</th></tr></thead><tbody>${pool.map(({p,t})=>`<tr><td><button class="namebutton" onclick="profile(${p.id})">${escapeHTML(p.name)}</button></td><td>${escapeHTML(t.abbr)}</td><td>${p.pos}</td><td>${p.age}</td><td>${ratingMarkup(p.ovr)}</td><td>${money(p.salary)}</td><td>${a.picks.filter(x=>x.from===t.id).length} / ${a.config.maximum}</td><td><button onclick="pickExpansionPlayer(${p.id})" ${a.phase!=='draft'||a.picks.length>=a.config.target?'disabled':''}>Select</button></td></tr>`).join('')||'<tr><td colspan="8">No eligible players match these filters.</td></tr>'}</tbody></table></div></section>${history}`;
}
function expansionAlignmentText(rows){return rows.map(r=>`<p>${escapeHTML(r.name)} <small>· ${escapeHTML(r.conference)} / ${escapeHTML(r.division)}</small></p>`).join('')}
function expansionHype(h){const t=state.teams[h.team],games=t.w+t.l,age=Math.max(0,state.year-h.year-1);return Math.max(10,Math.min(100,h.hype-age*15-Math.max(0,.5-t.w/(games||2))*Math.min(games,60)*1.2))}
const expansionProjectionBefore=financeProjection;financeProjection=function(club,playoffs=false,plan=null){const p=expansionProjectionBefore(club,playoffs,plan),h=state.expansion?.history.find(h=>h.team===club.id);if(h){p.capacity=h.config.capacity+financeFor(club).level*1000;p.attendance=Math.max(.2,Math.min(1,p.attendance+(expansionHype(h)-50)*.002))}return p};
function readExpansion(raw,teams,year,bad){
 if(raw===undefined)return undefined;const fail=()=>bad('invalid expansion data');if(!raw||!Array.isArray(raw.history)||raw.history.length>32)fail();
 const validId=id=>Number.isInteger(id)&&id>=0&&id<teams.length,validPlayer=id=>Number.isInteger(id)&&id>=0&&id<=10000000;
 const alignment=rows=>Array.isArray(rows)&&rows.length<=36&&rows.every(r=>validId(r.id)&&['name','conference','division'].every(k=>typeof r[k]==='string'&&r[k].length<=80));
 const picks=rows=>Array.isArray(rows)&&rows.length<=30&&new Set(rows.map(r=>r.id)).size===rows.length&&rows.every(r=>validPlayer(r.id)&&validId(r.from)&&typeof r.name==='string'&&r.name.length<=80&&['PG','SG','SF','PF','C'].includes(r.pos)&&Number.isFinite(r.salary)&&r.salary>=0&&r.salary<=1000);
 const config=c=>{try{return expansionConfig(c)}catch(e){fail()}};
 const history=raw.history.map(h=>{if(!h||!Number.isInteger(h.year)||h.year<1900||h.year>year||!validId(h.team)||h.team!==h.priorCount||h.priorCount<4||typeof h.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(h.date)||!h.vote||h.vote.yes!==h.priorCount||h.vote.no!==0||!picks(h.roster)||!alignment(h.before)||!alignment(h.after)||h.before.length!==h.priorCount||h.after.length!==h.priorCount+1||!Number.isFinite(h.hype)||h.hype<0||h.hype>100)fail();const c=config(h.config);if(h.roster.length!==c.target)fail();return {...copy(h),config:c}});
 if(new Set(history.map(h=>h.year)).size!==history.length||new Set(history.map(h=>h.team)).size!==history.length)fail();
 let active=null;if(raw.active){const a=raw.active,c=config(a.config);if(a.year!==year||history.some(h=>h.year===year)||!['protection','draft'].includes(a.phase)||!picks(a.picks)||!alignment(a.before)||!a.protected||typeof a.protected!=='object'||a.picks.length>c.target||a.phase==='protection'&&a.picks.length)fail();for(const t of teams){const ids=a.protected[t.id];if(!Array.isArray(ids)||ids.length>c.protect||new Set(ids).size!==ids.length||ids.some(id=>!validPlayer(id)))fail();const selected=a.picks.filter(p=>p.from===t.id);if(selected.length>c.maximum||selected.some(p=>ids.includes(p.id)))fail()}active={year,phase:a.phase,config:c,protected:copy(a.protected),picks:copy(a.picks),before:copy(a.before)}}
 return {active,history};
}

function expansionPendingSeason(club){return !!state.expansion?.history.some(h=>h.team===club.id&&h.year===state.year)}
const expansionArchiveStatsBefore=archiveStatsSeason;archiveStatsSeason=function(){if(state.expansion?.history.some(h=>h.year===state.year)&&state.statsArchive?.some(r=>r.year===state.year))return;return expansionArchiveStatsBefore()};
const expansionArchiveTeamBefore=archiveTeamStatsSeason;archiveTeamStatsSeason=function(){if(state.expansion?.history.some(h=>h.year===state.year)&&state.teamStatsArchive?.some(r=>r.year===state.year))return;return expansionArchiveTeamBefore()};
const expansionOwnerPlanBefore=ownerNewPlan;ownerNewPlan=function(club){const p=expansionOwnerPlanBefore(club),h=state.expansion?.history.find(h=>h.team===club.id);if(h&&state.year===h.year+1)p.ticketPrice=h.config.ticket;return p};

// Optional presets prefill the form; every field stays editable before the vote.
function expansionPresetsAvailable(){return FRANCHISE_PRESETS.filter(p=>!state.teams.some(t=>t.abbr===p.abbr||(t.city===p.city&&t.name===p.name)))}
function expansionPresetPicker(){const list=expansionPresetsAvailable();if(!list.length)return '';return `<details class="exp-presets"><summary>Start from a franchise preset (${list.length} available)</summary><div class="team-picker">${list.map(p=>presetCard(p,`<button type="button" class="primary" onclick="applyExpansionPreset('${p.abbr}')">Use preset</button>`)).join('')}</div><p class="muted">Presets fill in the form below. Edit any field before admitting the franchise; the preset logo stays unless you clear the preset.</p></details>`}
function applyExpansionPreset(abbr){const p=franchisePreset(abbr),form=document.getElementById('expansion-form');if(!p||!form)return;const t=presetTeamDefinition(p),f=form.elements,set=(k,v)=>{if(f[k])f[k].value=v};
 set('preset',p.abbr);set('city',p.city);set('name',p.name);set('abbr',p.abbr);set('primary',t.colors[0].hex.toLowerCase());set('secondary',t.colors[1].hex.toLowerCase());set('arenaName',p.arenaName);set('capacity',p.capacity);set('population',metroPopulationMillions(p.population));f.population?.dispatchEvent(new Event('input'));
 if(state.divisions.some(d=>d.id===p.divisionId))set('divisionId',p.divisionId);
 const preview=document.getElementById('expansion-preset-preview');if(preview)preview.innerHTML=`${presetLogo(p)}<div><strong>${escapeHTML(p.city+' '+p.name)}</strong><p class="muted">${escapeHTML(presetGeoLine(p))}</p><button type="button" onclick="clearExpansionPreset()">Clear preset</button></div>`;
 form.scrollIntoView?.({behavior:'smooth',block:'start'});toast(p.city+' '+p.name+' loaded. Review and edit before admitting.')}
function clearExpansionPreset(){const form=document.getElementById('expansion-form');if(!form)return;form.elements.preset.value='';const preview=document.getElementById('expansion-preset-preview');if(preview)preview.innerHTML=''}
